  const ripMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColor: { value: new THREE.Color(0xBFE0F0) },
      uOpacity: { value: 0.5 },
    },
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    vertexShader: /* glsl */`
      uniform float uTime;
      attribute vec4 aOffset;   // x, z, phase, size
      attribute float aY;
      varying vec2 vUv;
      varying float vAge;

      void main() {
        // 每个涟漪有自己的周期（1.2~2.2s），相位随机错开
        float period = 1.2 + aOffset.z * 1.0;
        // age: 0..1 循环
        float age = fract(uTime / period + aOffset.z);
        vAge = age;

        // 平面铺在地面，按 age 放大
        float s = aOffset.w * (0.25 + age * 2.2);
        vec3 p = vec3(position.x * s, 0.0, position.y * s);
        p.x += aOffset.x;
        p.z += aOffset.y;
        p.y = aY;

        vUv = position.xy;
        gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
      }
    `,
    fragmentShader: /* glsl */`
      uniform vec3  uColor;
      uniform float uOpacity;
      varying vec2 vUv;
      varying float vAge;

      void main() {
        float d = length(vUv) * 2.0;      // 0..1 半径
        // 圆环：环形高斯
        float ring = smoothstep(0.0, 0.12, abs(d - 0.85)) ;
        ring = 1.0 - ring;
        // 内圈再补一道淡环
        float ring2 = 1.0 - smoothstep(0.0, 0.08, abs(d - 0.5));
        float a = (ring * 0.9 + ring2 * 0.25);
        // 随时间淡出 + 外圈更淡
        a *= (1.0 - vAge) * uOpacity * smoothstep(1.0, 0.85, d);
        if (a < 0.005) discard;
        gl_FragColor = vec4(uColor, a);
      }
    `,
  });
  const ripples = new THREE.Mesh(ripGeo, ripMat);
  ripples.frustumCulled = false;
  scene.add(ripples);

  return { pts, mat, ripples, ripMat };
}

