const ripCount = CONFIG.quality === 'low' ? Math.floor(CONFIG.rippleCount / 2) : CONFIG.rippleCount;
// 注意：InstanceBufferGeometry 才能读到 per-instance attribute，普通 BufferGeometry 不会。
const base = new THREE.PlaneGeometry(1, 1);
const ripGeo = new THREE.InstancedBufferGeometry();
ripGeo.index = base.index;
ripGeo.setAttribute('position', base.getAttribute('position'));
ripGeo.setAttribute('uv', base.getAttribute('uv'));
ripGeo.instanceCount = ripCount;

float d = length(vUv) * 2.0;      // 0..1 半径
// 主圆环：距离 0.85 处最亮，向内外快速衰减
float ring = 1.0 - smoothstep(0.0, 0.13, abs(d - 0.85));
// 内圈再补一道淡环
float ring2 = 1.0 - smoothstep(0.0, 0.09, abs(d - 0.5));
float a = ring * 0.9 + ring2 * 0.25;
// 硬边裁掉圆外区域，避免方形的四个角露出来
a *= step(d, 1.0);
// 随时间淡出
a *= (1.0 - vAge) * uOpacity;
if (a < 0.005) discard;
gl_FragColor = vec4(uColor, a);

