edits.newText:
const bldMat = new THREE.MeshStandardMaterial({ color: 0x1A2128, roughness: 1.0, metalness: 0.0 });
const winMat = new THREE.MeshBasicMaterial({ color: 0xFFCF8A });
const blds = [
  [-22, 9, -22, 10, 8, 12], [22, 7, -24, 9, 14, 10], [0, 11, -34, 26, 22, 10],
  [-30, 6, -16, 8, 12, 10], [30, 8, -18, 10, 16, 12],
];
for (const [x, hh, z, w, h, d] of blds) {
  const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), bldMat);
  b.position.set(x, h / 2, z);
  scene.add(b);
  // 零星亮窗：贴近建筑正面（z + d/2），按网格排列，低概率点亮
  const winW = 0.62, winH = 0.85, gapX = 1.5, gapY = 1.7;
  const cols = Math.floor((w - 1.2) / gapX), rowsN = Math.floor((h - 3) / gapY);
  for (let r = 0; r < rowsN; r++) {
    for (let c = 0; c < cols; c++) {
      if (Math.random() > 0.16) continue;
      const win = new THREE.Mesh(new THREE.PlaneGeometry(winW, winH), winMat.clone());
      win.material.color.setHSL(rnd(0.07, 0.13), rnd(0.25, 0.7), rnd(0.22, 0.45));
      win.position.set(
        x - (cols - 1) * gapX / 2 + c * gapX,
        2.2 + r * gapY,
        z + d / 2 + 0.02
      );
      scene.add(win);
    }
  }
}

