/* ============================================================================
   5. 灯光
   ========================================================================== */
function createLighting(store) {
  const L = {};
  const { W, faceZ, baseY, fridgeZ } = store.userData;

  // 环境光：极暗
  scene.add(new THREE.HemisphereLight(CONFIG.hemiSky, CONFIG.hemiGround, CONFIG.hemiIntensity));

  // 室内矩形面光（2 个，等效灯管）
  const r1 = new THREE.RectAreaLight(CONFIG.storeLightColor, CONFIG.storeLightIntensity, W - 1.5, 1.6);
  r1.position.set(0, baseY + 3.7, faceZ - 1.6);
  r1.lookAt(0, 0, faceZ + 2);
  scene.add(r1);
  const r2 = new THREE.RectAreaLight(CONFIG.storeLightColor, CONFIG.storeLightIntensity * 0.8, W - 1.5, 1.2);
  r2.position.set(0, baseY + 3.7, faceZ - 4.2);
  r2.lookAt(0, 0, faceZ + 2);
  scene.add(r2);

  // 店内点光，照亮货架与收银
  const inner = new THREE.PointLight(CONFIG.storeLightColor, 14, 12, 2);
  inner.position.set(0, baseY + 3.2, faceZ - 2.4);
  scene.add(inner);

  // 冷柜发光照明
  const fridgeLight = new THREE.PointLight(0x9FEBFF, 8, 7, 2);
  fridgeLight.position.set(0, baseY + 1.4, fridgeZ + 1.0);
  scene.add(fridgeLight);

  // 门口暖白光斑：SpotLight 从门上方往下打
  const spot = new THREE.SpotLight(0xEAF2FF, 22, 14, Math.PI / 5.2, 0.65, 1.8);
  spot.position.set(0, baseY + 3.6, faceZ + 1.0);
  spot.target.position.set(0, 0, faceZ + 4.4);
  scene.add(spot); scene.add(spot.target);

  // 地面光斑贴图（加法混合的圆形渐变，省性能的补充）
  const blobTex = canvasTex(256, 256, (ctx, w, h) => {
    const grd = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    grd.addColorStop(0, 'rgba(255,255,255,0.85)');
    grd.addColorStop(0.45, 'rgba(200,230,255,0.28)');
    grd.addColorStop(1, 'rgba(200,230,255,0)');
    ctx.fillStyle = grd; ctx.fillRect(0, 0, w, h);
  }, { srgb: false });
  const blob = new THREE.Mesh(new THREE.PlaneGeometry(9, 9),
    new THREE.MeshBasicMaterial({
      map: blobTex, transparent: true, opacity: 0.22,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
  blob.rotation.x = -Math.PI / 2;
  blob.position.set(0, 0.16, faceZ + 3.2);
  scene.add(blob);
  L.blob = blob;

  // 霓虹染色点光
  const neonLight = new THREE.PointLight(CONFIG.neonColor, 10, 9, 2);
  neonLight.position.set(W / 2 + 0.5, baseY + 2.6, faceZ + 0.9);

  g.userData = { tubes, neonPanel, neonGroup, door, awningStrip, rainStreakTex, rainGlass, signLightbox, W, D, H, faceZ, baseY, fridgeZ };
  return g;
}

